// random_selector / simple_random_selector / random_boolean_selector:
// a child list (`chance` is a probability for the weighted selector, a
// weight for the simple one, and ignored for the boolean one) plus the
// weighted selector's default feature.
// `kind`: 0 a placed feature (run its own placement first), 1 a configured feature placed directly.
struct WgSelectorChild { const char* feature; float chance; uint8_t kind; };
struct WgSelector {
  uint8_t kind; // 0 random_selector, 1 simple_random_selector, 2 boolean
  uint32_t offset;
  uint32_t count;
  const char* default_feature;
};

